#pragma config(Motor,  port3,        pressArmServoA, tmotorServoStandard, openLoop)
#pragma config(Motor,  port4,        pressArmServoB, tmotorServoStandard, openLoop)
//*!!Code automatically generated by 'ROBOTC' configuration wizard               !!*//

/*
  Servo angle test for the press arm (two servos, motor ports 3 and 4).

  A VEX servo turns about 100 degrees in total. The command goes from -127 to +127:
      -127  ~ -50 degrees
         0  =   0 degrees (center)
      +127  ~ +50 degrees
  so 1 degree is about 2.5 command units.

  How to use:
    1. Put the robot on a box. Keep hands and the beacon away from the arm.
    2. Download, open Robot > Debugger Windows > Debug Stream, press Start.
    3. Direction check: the arm goes to the center, then makes a small move (+20).
       If the servos buzz or the arm twists, switch the robot OFF and flip
       PRESS_ARM_B_SIGN (here and in robot_project.c).
    4. The arm then steps through the positions below, 2 seconds each.
       Write down which number is "arm up, out of the way" (PRESS_ARM_HOME_POS)
       and which number just presses the beacon's button (PRESS_ARM_BUTTON_POS),
       then put them in robot_project.c.

  If the arm hits something or a servo buzzes and strains, switch the robot off:
  that position is past what the arm can reach.
*/

#define PRESS_ARM_B_SIGN    -1    // must match robot_project.c
#define STEP_SIZE           20    // command units between test positions (~8 degrees)
#define HOLD_TIME_MS      2000    // how long to hold each position

void SetPressArm(int position)
{
    motor[pressArmServoA] = position;
    motor[pressArmServoB] = position * PRESS_ARM_B_SIGN;
}

task main()
{
    int position;

    clearDebugStream();

    writeDebugStreamLine("CENTER: pos=0 (~0 deg)");
    SetPressArm(0);
    wait1Msec(3000);

    writeDebugStreamLine("DIRECTION CHECK: pos=20 - buzzing or twisting? switch OFF, flip PRESS_ARM_B_SIGN");
    SetPressArm(20);
    wait1Msec(3000);

    for(position = -120; position <= 120; position += STEP_SIZE)
    {
        writeDebugStreamLine("pos=%d (~%d deg)", position, position * 50 / 127);
        SetPressArm(position);
        wait1Msec(HOLD_TIME_MS);
    }

    writeDebugStreamLine("DONE - back to center");
    SetPressArm(0);
    wait1Msec(1000);
}
